package com.ragpipeline.exception;import org.springframework.http.*;import org.springframework.web.bind.annotation.*;import java.util.Map;@RestControllerAdvice public class GlobalExceptionHandler{@ExceptionHandler(Exception.class)ResponseEntity<Map<String,String>> error(Exception e){return ResponseEntity.status(HttpStatus.INTERNAL_SERVER_ERROR).body(Map.of("error",e.getMessage()==null?"Unexpected error":e.getMessage()));}}
